import json,os
def shapes(g):
    s={}
    for r in g:
        for c in r:
            if c: s.setdefault(c,[0,0,0,0]); 
    for c in s:
        cells=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==c]
        s[c]=[min(i for i,_ in cells),min(j for _,j in cells),max(i for i,_ in cells),max(j for _,j in cells)]
    return s
def f(g):
    n=len(g); out=[[0]*n for _ in range(n)]
    s=shapes(g); cols=sorted(s)
    shapes_cells={}
    for c in s:
        shapes_cells[c]=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==c]
    t,l=0,0
    for c in cols:
        i0,j0,i1,j1=s[c]; h,w=i1-i0+1,j1-j0+1
        if c!=cols[0]:
            t,l=pt+ph-1,pl+pw-1
        for i,j in shapes_cells[c]:
            out[t+i-i0][l+j-j0]=c
        pt,pl,ph,pw=t,l,h,w
    return out
